#include <Python.h>
#include <openssl/evp.h>
#include <pthread.h>
#include <string.h>
#include <stdlib.h>

typedef unsigned long long u64;
typedef __uint128_t u128;

#define MASK44 0xfffffffffffULL
#define MASK42 0x3ffffffffffULL

static u64 U8TO64(const unsigned char *p) {
    return ((u64)p[0]) | ((u64)p[1]<<8) | ((u64)p[2]<<16) | ((u64)p[3]<<24) |
           ((u64)p[4]<<32) | ((u64)p[5]<<40) | ((u64)p[6]<<48) | ((u64)p[7]<<56);
}

static void U64TO8(unsigned char *p, u64 v) {
    p[0]=v&0xff; p[1]=(v>>8)&0xff; p[2]=(v>>16)&0xff; p[3]=(v>>24)&0xff;
    p[4]=(v>>32)&0xff; p[5]=(v>>40)&0xff; p[6]=(v>>48)&0xff; p[7]=(v>>56)&0xff;
}

// multiply two 3-limb (44,44,42) numbers mod 2^130-5
static void mul_mod(u64 *out, const u64 *a, const u64 *b) {
    u128 d0 = (u128)a[0]*b[0] + (u128)a[1]*b[2]*20 + (u128)a[2]*b[1]*20;
    u128 d1 = (u128)a[0]*b[1] + (u128)a[1]*b[0] + (u128)a[2]*b[2]*20;
    u128 d2 = (u128)a[0]*b[2] + (u128)a[1]*b[1] + (u128)a[2]*b[0];
    u64 c = (u64)(d0 >> 44); out[0] = (u64)d0 & MASK44;
    d1 += c; c = (u64)(d1 >> 44); out[1] = (u64)d1 & MASK44;
    d2 += c; c = (u64)(d2 >> 42); out[2] = (u64)d2 & MASK42;
    out[0] += c*5; c = out[0] >> 44; out[0] &= MASK44;
    out[1] += c;
}

static void add_mod(u64 *out, const u64 *a, const u64 *b) {
    u64 c;
    out[0] = a[0] + b[0]; c = out[0] >> 44; out[0] &= MASK44;
    out[1] = a[1] + b[1] + c; c = out[1] >> 44; out[1] &= MASK44;
    out[2] = a[2] + b[2] + c; c = out[2] >> 42; out[2] &= MASK42;
    out[0] += c*5; c = out[0] >> 44; out[0] &= MASK44;
    out[1] += c;
}

static void pow_mod(u64 *out, const u64 *base, u64 exp) {
    u64 result[3] = {1,0,0};
    u64 b[3] = {base[0], base[1], base[2]};
    while (exp) {
        if (exp & 1) mul_mod(result, result, b);
        mul_mod(b, b, b);
        exp >>= 1;
    }
    out[0]=result[0]; out[1]=result[1]; out[2]=result[2];
}

// process blocks: h = (h + m) * r for each 16-byte block, no hibit
static void poly1305_blocks(u64 *h, const u64 *r, const unsigned char *m, size_t nbytes) {
    u64 r0=r[0], r1=r[1], r2=r[2];
    u64 s1 = r1*20, s2 = r2*20;
    u64 h0=h[0], h1=h[1], h2=h[2];
    while (nbytes >= 16) {
        h0 += U8TO64(m) & MASK44;
        h1 += (U8TO64(m+8) >> 4) & MASK44;
        h2 += (U8TO64(m+8) >> 8) & MASK42;
        u128 d0 = (u128)h0*r0 + (u128)h1*s2 + (u128)h2*s1;
        u128 d1 = (u128)h0*r1 + (u128)h1*r0 + (u128)h2*s2;
        u128 d2 = (u128)h0*r2 + (u128)h1*r1 + (u128)h2*r0;
        u64 c = (u64)(d0 >> 44); h0 = (u64)d0 & MASK44;
        d1 += c; c = (u64)(d1 >> 44); h1 = (u64)d1 & MASK44;
        d2 += c; c = (u64)(d2 >> 42); h2 = (u64)d2 & MASK42;
        h0 += c*5; c = h0 >> 44; h0 &= MASK44;
        h1 += c;
        m += 16; nbytes -= 16;
    }
    h[0]=h0; h[1]=h1; h[2]=h2;
}
