        char name[256]; clGetDeviceInfo(devs[d], CL_DEVICE_NAME, 256, name, NULL);
        cl_int err;
        cl_context ctx = clCreateContext(NULL,1,&devs[d],NULL,NULL,&err);
        cl_command_queue q = clCreateCommandQueue(ctx, devs[d], 0, &err);
        unsigned char *host = malloc(N);
        memset(host, 1, N);
        cl_mem buf = clCreateBuffer(ctx, CL_MEM_READ_WRITE, N, NULL, &err);
        // warm
        clEnqueueWriteBuffer(q, buf, CL_TRUE, 0, N, host, 0,NULL,NULL);
        clEnqueueReadBuffer(q, buf, CL_TRUE, 0, N, host, 0,NULL,NULL);
        // H2D
        double best=1e9;
        for(int r=0;r<10;r++){ double t0=now(); clEnqueueWriteBuffer(q, buf, CL_TRUE, 0, N, host, 0,NULL,NULL); double t1=now(); if(t1-t0<best)best=t1-t0; }
        printf("%s: H2D %.2f ms (%.2f GB/s)\n", name, best*1000, N/best/1e9);
        // D2H
        best=1e9;
        for(int r=0;r<10;r++){ double t0=now(); clEnqueueReadBuffer(q, buf, CL_TRUE, 0, N, host, 0,NULL,NULL); double t1=now(); if(t1-t0<best)best=t1-t0; }
        printf("%s: D2H %.2f ms (%.2f GB/s)\n", name, best*1000, N/best/1e9);
        clReleaseMemObject(buf); clReleaseCommandQueue(q); clReleaseContext(ctx);
    }
    return 0;
}
